      "title": "BIBB/IAB Qualification and Course of Employment Survey 1979",
      "url_or_doi": "https://doi.org/10.4232/1.1243",
      "justification": "Conducted in 1979 by BIBB and IAB, this dataset captures baseline data entering the 1980s on the West German workforce across federal states (including Hesse). It details vocational education trajectories, workplace equipment, physical/health working conditions, and job safety characteristics."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core, 1984 onwards)",
      "url_or_doi": "https://doi.org/10.5684/soep.core.v40eu",
      "justification": "Launched in 1984, SOEP is a multi-decade longitudinal study of private households and individuals in Germany containing federal state identifiers (including Hesse). It tracks occupational health, working conditions, job satisfaction, and vocational education and training paths year by year throughout the 1980s."
    },
    {
      "title": "German General Social Survey (ALLBUS) 1984",
      "url_or_doi": "https://doi.org/10.4232/1.1340",
      "justification": "Conducted in West Germany in 1984, this representative survey includes regional indicators for Hesse and measures respondents' vocational training background, current employment status, job characteristics, and health and working condition aspects as part of its core focus on social inequality."
    }
  ]
